// FIXTURE (synthetic, not owner data): a representative persisted schema-5 world with 300+ residents and resources
// accumulated by the BASE engine (d0ee752), i.e. including the ground-pile "log carpet" this change addresses.
//   node tests/fixtures/expanse-v5-300/make-fixture.mjs <base-checkout-root> [ticks]
import fs from 'node:fs'; import path from 'node:path'; import zlib from 'node:zlib'; import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';
const root = path.resolve(process.argv[2]), ticks = Number(process.argv[3] ?? 1500), here = path.dirname(new URL(import.meta.url).pathname);
const { Expanse } = await import(pathToFileURL(path.join(root, 'server/src/expanse/engine.js')).href);
const e = Expanse.create({ initialCount: 320, maxDecisionsPerTick: 96 }, { seed: 11 }); e.id = 'fixture-schema5-300-seed11';
e.run(ticks);
const state = e.toState(), body = zlib.gzipSync(JSON.stringify(state), { level: 9 });
let piles = 0, pileUnits = 0; for (const ch of e.chunks.values()) for (const p of ch.piles) { piles++; for (const v of Object.values(p.items)) pileUnits += v; }
fs.writeFileSync(path.join(here, 'expanse.json.gz'), body);
fs.writeFileSync(path.join(here, 'manifest.json'), JSON.stringify({ fixture: true, note: 'Synthetic test fixture generated by the base engine; not a copy of any owner/live world.', generator: 'make-fixture.mjs', baseCommit: 'd0ee752960b66ac04c8f36964e195d9409d97bfb', seed: 11, initialCount: 320,
  file: 'expanse.json.gz', sha256: crypto.createHash('sha256').update(body).digest('hex'), bytes: body.length, schema: state.schema, tick: state.tick, residents: state.creatures.length, shelters: e.shelters.length, piles, pileUnits }, null, 1));
console.log(JSON.stringify({ tick: state.tick, residents: state.creatures.length, piles, pileUnits, bytes: body.length }));
